<?php $title='Penilaian Tugas';$page='submissions';$pdo=Database::connection();$uid=current_user()['id'];$q=$pdo->prepare('SELECT s.*,u.name student_name,t.title task_title,m.title module_title FROM submissions s JOIN users u ON u.id=s.student_id JOIN tasks t ON t.id=s.task_id JOIN modules m ON m.id=t.module_id WHERE m.teacher_id=? ORDER BY s.submitted_at DESC');$q->execute([$uid]);$rows=$q->fetchAll();require __DIR__.'/../_dashboard_start.php'; ?>
<div class="page-heading"><div><h1>Penilaian Tugas</h1><p>Periksa jawaban dan berikan nilai serta umpan balik kepada siswa.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Siswa</th><th>Tugas / Modul</th><th>Jawaban</th><th>Nilai</th><th>Umpan Balik</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['student_name']) ?><small class="block muted"><?= e(format_date($r['submitted_at'])) ?></small></td><td><?= e($r['task_title']) ?><small class="block muted"><?= e($r['module_title']) ?></small></td><td class="answer-cell"><?= e($r['answer_text']) ?><?php if(!empty($r['file_path'])): ?><br><a target="_blank" rel="noopener" href="<?= e(url($r['file_path'])) ?>">Lihat lampiran</a><?php endif; ?></td><td><?= $r['score']===null?'Belum dinilai':e($r['score']) ?></td><td><?= e($r['feedback']??'—') ?></td><td><button class="btn btn-small btn-primary grade-btn" data-id="<?= $r['id'] ?>" data-score="<?= e($r['score']??'') ?>" data-feedback="<?= e($r['feedback']??'') ?>">Nilai</button></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$rows): ?><div class="empty-state">Belum ada tugas yang dikumpulkan.</div><?php endif; ?></section>
<div class="modal" id="gradeModal"><form class="modal-card" id="gradeForm"><?= csrf_field() ?><input type="hidden" name="submission_id"><h3>Berikan Penilaian</h3><label>Nilai (0–100)<input type="number" name="score" min="0" max="100" step="0.01" required></label><label>Umpan balik<textarea name="feedback" rows="4"></textarea></label><div class="modal-actions"><button type="button" class="btn btn-light" data-close> Batal</button><button class="btn btn-primary">Simpan Nilai</button></div></form></div>
<?php require __DIR__.'/../_dashboard_end.php'; ?>